import type {
	ControlledMode,
	EvaluationScenario,
} from "../../src/services/evaluation/ab-contracts.js";

const SNAPSHOT = "ab-local-synthetic-snapshot-v1";
const ACTOR = "demo-customer-1";

/** Only Structured query plans that exist in the shipped catalog. */
export const STRUCTURED_QUERY_PLAN_ALLOWLIST = [
	"customer_products",
	"product_status",
	"recent_transactions",
] as const;

/** Only KG analytic cases published for kg.case.summary. */
export const KG_CASE_ALLOWLIST = ["C1", "C2", "C3", "C4", "C5"] as const;

const gatesOn = {
	controlPlane: true,
	privacy: true,
	guardrail: true,
	policy: true,
} as const;

const gatesEarlyFail = {
	controlPlane: true,
	privacy: true,
	guardrail: true,
	policy: false,
} as const;

function scenario(
	partial: Omit<EvaluationScenario, "actorId" | "snapshotId"> &
		Partial<Pick<EvaluationScenario, "actorId" | "snapshotId">>,
): EvaluationScenario {
	return {
		actorId: ACTOR,
		snapshotId: SNAPSHOT,
		...partial,
	};
}

type Shared = {
	phase: "phase-1" | "phase-2";
	polarity: "positive" | "negative";
	expectedRoute: EvaluationScenario["expectedRoute"];
	expectedQueryPlanId: string | null;
	expectedTerminalStatus: EvaluationScenario["expectedTerminalStatus"];
	expectedRetrieval: boolean;
	controlledMode: ControlledMode;
	controlledExpectsGates: typeof gatesOn | typeof gatesEarlyFail;
	researchRef: string | null;
};

/** Build an ES/PT mirror pair with the same control-plane expectations. */
function bilingual(
	id: string,
	esPrompt: string,
	ptPrompt: string,
	shared: Shared,
): EvaluationScenario[] {
	return [
		scenario({
			scenarioId: `${id}-es`,
			locale: "es",
			prompt: esPrompt,
			...shared,
		}),
		scenario({
			scenarioId: `${id}-pt`,
			locale: "pt",
			prompt: ptPrompt,
			...shared,
		}),
	];
}

